// Parse Claude's response and extract the JSON
const claudeResponse = $input.first().json;
const textContent = claudeResponse.content?.[0]?.text || '';

let parsed;
try {
  // Try to extract JSON from the response
  const jsonMatch = textContent.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found');
  }
} catch (e) {
  // Fallback if Claude didn't return valid JSON
  parsed = {
    reply: textContent || 'Désolée, je n\'ai pas compris. Pouvez-vous reformuler ?',
    buttons: [
      { label: '🍛 Voir la carte', value: 'voir_carte' },
      { label: '💬 Parler à l\'équipe', value: 'commander_whatsapp' }
    ],
    signal: 'cold'
  };
}

// Add session and usage metadata
parsed.sessionId = $node['Webhook Vanessa Chat'].json.body?.sessionId || 'unknown';
parsed.usage = {
  input_tokens: claudeResponse.usage?.input_tokens || 0,
  output_tokens: claudeResponse.usage?.output_tokens || 0
};

return [{ json: parsed }];

// Log the conversation event for analytics
const body = $node['Webhook Vanessa Chat'].json.body || {};
const parsed = $node['Parse Claude Response'].json;

const event = {
  timestamp: new Date().toISOString(),
  sessionId: body.sessionId || 'unknown',
  userMessage: body.message || '',
  botReply: parsed.reply || '',
  signal: parsed.signal || 'cold',
  buttons: parsed.buttons || [],
  page: body.page || '/',
  inputTokens: parsed.usage?.input_tokens || 0,
  outputTokens: parsed.usage?.output_tokens || 0
};

return [{ json: event }];
